const f = $input.first().json;
const pick = (o, k) => (o[k] === undefined || o[k] === null ? '' : String(o[k]).trim());
return [{ json: { baseId: pick(f, 'Clayroots Base ID'), tableId: pick(f, 'Table ID'), tag: pick(f, 'Tag'), buildDate: pick(f, 'Build Date'), launchRecordId: '', triggerKind: 'form' } }];

const i = $input.first().json;
const baseId = String(i.baseId || '').trim();
const tableId = String(i.tableId || '').trim();
const tag = String(i.tag || '').trim();
const buildDate = String(i.buildDate || '').trim();
if (!/^app[A-Za-z0-9]{14}$/.test(baseId)) {
  throw new Error('Clayroots Base ID ' + baseId + ' is not a valid base id. Nothing was written.');
}
if (!/^tbl[A-Za-z0-9]{14}$/.test(tableId)) {
  throw new Error('Table ID ' + tableId + ' is not a valid table id. Nothing was written.');
}
if (!tag) {
  throw new Error('No Tag value was supplied for table ' + tableId + '. The Tag is the whole point of this run. Nothing was written.');
}
if (buildDate && !/^\d{4}-\d{2}-\d{2}$/.test(buildDate)) {
  throw new Error('Build Date filter ' + buildDate + ' is not an ISO date in the form YYYY-MM-DD. Nothing was written.');
}
return [{ json: { baseId, tableId, tag, buildDate, launchRecordId: String(i.launchRecordId || ''), triggerKind: String(i.triggerKind || 'form'), startedAt: new Date().toISOString() } }];

const client = $input.first().json;
const launch = $('Read Launch Record').first().json;
const hook = $('Launch Webhook').first().json || {};
const q = hook.query || {};
const baseId = String(client['Clayroots Base ID'] || '').trim();
const tableId = String(launch['Table ID'] || launch['Target'] || '').trim();
const tag = String(q.tag || launch['Tag'] || '').trim();
const buildDate = String(q.buildDate || '').trim();
if (!/^app[A-Za-z0-9]{14}$/.test(baseId)) {
  throw new Error('The launch record does not resolve to a Clayroots Base ID. Nothing was written.');
}
return [{ json: { baseId, tableId, tag, buildDate, launchRecordId: String(launch.id || ''), triggerKind: 'webhook' } }];

const cfg = $('Resolve Inputs').first().json;
const tables = [];
for (const it of $input.all()) {
  const r = it.json;
  if (Array.isArray(r.tables)) { for (const t of r.tables) tables.push(t); }
  else if (r && r.id) tables.push(r);
}
const table = tables.find(t => t && t.id === cfg.tableId);
if (!table) {
  throw new Error('Table ' + cfg.tableId + ' does not resolve in base ' + cfg.baseId + '. Nothing was written.');
}
const tableName = table.name || cfg.tableId;
const fields = table.fields || [];
const tagField = fields.find(f => f && f.name === 'Tag');
if (!tagField) {
  throw new Error('Table ' + tableName + ' (' + cfg.tableId + ') in base ' + cfg.baseId + ' has no Tag column. This automation never creates fields: add the Tag column by hand, then re-run. Nothing was written.');
}
const COMPUTED = ['formula','rollup','count','lookup','multipleLookupValues','aiText','autoNumber','createdTime','lastModifiedTime','createdBy','lastModifiedBy','button','externalSyncSource','barcode'];
if (COMPUTED.indexOf(tagField.type) > -1) {
  throw new Error('The Tag column on ' + tableName + ' (' + cfg.tableId + ') is a computed field (' + tagField.type + ') and cannot be written. Nothing was written.');
}
let formula = '';
let filterNote = 'whole table, no Build Date filter';
if (cfg.buildDate) {
  const bd = fields.find(f => f && f.name === 'Build Date');
  if (!bd) {
    throw new Error('A Build Date filter of ' + cfg.buildDate + ' was requested but table ' + tableName + ' (' + cfg.tableId + ') has no Build Date column. Nothing was written.');
  }
  formula = "IS_SAME({Build Date}, DATETIME_PARSE('" + cfg.buildDate + "', 'YYYY-MM-DD'), 'day')";
  filterNote = 'rows whose Build Date falls on ' + cfg.buildDate + ' (UTC day, date-mode comparison)';
}
const s = $getWorkflowStaticData('global');
s.stt = s.stt || {};
s.stt[$execution.id] = { scanned: 0, changed: 0, unchanged: 0, filled: 0, overwritten: 0, pages: 0, batches: 0 };
const baseUrl = 'https://api.airtable.com/v0/' + cfg.baseId + '/' + cfg.tableId + '?pageSize=100&fields%5B%5D=Tag' + (formula ? '&filterByFormula=' + encodeURIComponent(formula) : '');
return [{ json: { baseId: cfg.baseId, tableId: cfg.tableId, tableName, tag: cfg.tag, buildDate: cfg.buildDate, tagFieldType: tagField.type, formula, filterNote, baseUrl, pageUrl: baseUrl, more: true } }];

const cfg = $('Check Tag Column').first().json;
const s = $getWorkflowStaticData('global');
s.stt = s.stt || {};
if (!s.stt[$execution.id]) { s.stt[$execution.id] = { scanned: 0, changed: 0, unchanged: 0, filled: 0, overwritten: 0, pages: 0, batches: 0 }; }
const st = s.stt[$execution.id];

const readVal = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') { return typeof v.value === 'string' ? v.value : ''; }
  return String(v);
};

const resp = $input.first().json || {};
const records = Array.isArray(resp.records) ? resp.records : [];
const updates = [];
for (const rec of records) {
  const f = (rec && rec.fields) || {};
  st.scanned++;
  const current = readVal(f['Tag']);
  if (current === cfg.tag) { st.unchanged++; continue; }
  if (current.trim()) { st.overwritten++; } else { st.filled++; }
  updates.push({ id: rec.id, fields: { 'Tag': cfg.tag } });
  st.changed++;
}

const chunks = [];
for (let i = 0; i < updates.length; i += 10) { chunks.push({ records: updates.slice(i, i + 10) }); }
st.pages++;
st.batches += chunks.length;

const offset = resp.offset ? String(resp.offset) : '';
const nextUrl = offset ? (cfg.baseUrl + '&offset=' + encodeURIComponent(offset)) : '';
return [{ json: { chunks, chunkCount: chunks.length, pageUrl: nextUrl, more: !!offset } }];

const cfg = $('Check Tag Column').first().json;
const inp = $('Resolve Inputs').first().json;
const s = $getWorkflowStaticData('global');
s.stt = s.stt || {};
const st = s.stt[$execution.id] || { scanned: 0, changed: 0, unchanged: 0, filled: 0, overwritten: 0, pages: 0, batches: 0 };
delete s.stt[$execution.id];
const duration = Math.max(0, Math.round((Date.now() - new Date(inp.startedAt).getTime()) / 1000));
const description = 'Stamped Tag on ' + cfg.tableName + ' (' + cfg.tableId + ') in ' + cfg.baseId + '.\n' +
  'Tag written: ' + cfg.tag + '.\n' +
  'Scope: ' + cfg.filterNote + '.\n' +
  'Scanned ' + st.scanned + ', changed ' + st.changed + ', already carrying the tag ' + st.unchanged + '.\n' +
  'Of the changed rows: ' + st.filled + ' were blank, ' + st.overwritten + ' held a different Tag and were overwritten.\n' +
  'Pages read ' + st.pages + ', write batches ' + st.batches + '. Plain record updates, never an upsert. Build Date was never in a payload.';
const fields = {
  'Execution ID': String($execution.id),
  'Automation': 'Stamp Tag on table',
  'Status': 'Succeeded',
  'Description': description,
  'Run at': inp.startedAt,
  'Target': cfg.tableName,
  'Table ID': cfg.tableId,
  'Tag': cfg.tag,
  'Duration s': duration,
  'Execution Link': 'https://n8n.flowroots.com/workflow/' + $workflow.id + '/executions/' + $execution.id,
  'Records In': st.scanned,
  'Records Out': st.changed,
  'Errors': 0,
  'Trigger': inp.triggerKind === 'webhook' ? 'webhook' : 'form'
};
const body = inp.launchRecordId ? { records: [{ id: inp.launchRecordId, fields }], typecast: true } : { records: [{ fields }], typecast: true };
return [{ json: { hasLaunchRecord: !!inp.launchRecordId, body, summary: description } }];

const j = $input.first().json || {};
const q = j.query || {};
const s = (v) => (v === undefined || v === null ? '' : String(v).trim());
return [{ json: { baseId: s(q.baseId), tableId: s(q.tableId), tag: s(q.tag), buildDate: s(q.buildDate), launchRecordId: s(q.recordId), triggerKind: 'webhook' } }];
